1	/* The reader of the Fortress specification. The colours, the type sizes and the Select
2	   button come from the revival page (explorations/coordinator/process-engineering/
3	   revival-story.html); the fonts are the system's, since the reader loads nothing external. */
4	/* The curly quotation marks alone come from a serif face, as in the PDF: in a sans face they look like
5	   straight ticks, and the specification quotes single characters all the time. */
6	@font-face { font-family: "SpecQuotes"; src: local("Times New Roman"), local("TimesNewRomanPSMT"), local("STIX Two Text"), local("Georgia"), local("Nimbus Roman"), local("Liberation Serif"); unicode-range: U+2018-201F; }
7	:root {
8	  --bg: #f6f7f6; --surface: #ffffff; --fg: #1d2421; --muted: #5b6661; --rule: #d8dedb;
9	  --accent: #1f6f5c; --code-bg: #eef1ef; --note-bg: #fbf4e4; --note-rule: #d9b45c;
10	  --rev-bg: #e9f0f8; --rev-rule: #1c548c; --rev-fg: #17446f; --mark: #fff3b8;
11	  --body: "SpecQuotes", "Atkinson Hyperlegible", "Segoe UI", system-ui, -apple-system, sans-serif;
12	  --mono: "JetBrains Mono", ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
13	  --math: "STIX Two Text", "STIXGeneral", "Times New Roman", Times, "Nimbus Roman", serif;
14	}
15	@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) {
16	  --bg: #141917; --surface: #1b211f; --fg: #e3e8e5; --muted: #9aa6a0; --rule: #2d3632;
17	  --accent: #6cc4a8; --code-bg: #222a27; --note-bg: #2a2518; --note-rule: #8a7333;
18	  --rev-bg: #18232f; --rev-rule: #6aa6de; --rev-fg: #9cc6ee; --mark: #4a431c; color-scheme: dark } }
19	:root[data-theme="dark"] {
20	  --bg: #141917; --surface: #1b211f; --fg: #e3e8e5; --muted: #9aa6a0; --rule: #2d3632;
21	  --accent: #6cc4a8; --code-bg: #222a27; --note-bg: #2a2518; --note-rule: #8a7333;
22	  --rev-bg: #18232f; --rev-rule: #6aa6de; --rev-fg: #9cc6ee; --mark: #4a431c; color-scheme: dark }
23	
24	* { box-sizing: border-box; }
25	html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
26	body { background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 16px; line-height: 1.55;
27	  margin: 0; padding-inline: max(16px, env(safe-area-inset-left)) max(16px, env(safe-area-inset-right)); padding-block: 0 64px;
28	  overflow-wrap: break-word; }
29	.page { max-width: 46rem; margin: 0 auto; display: flex; flex-direction: column; gap: 24px; padding-top: 20px; }
30	.page > * { min-width: 0; }
31	h1 { font-size: 1.9rem; line-height: 1.2; margin: 0 0 .8rem; text-wrap: balance; }
32	h2 { font-size: 1.35rem; line-height: 1.25; margin: 0 0 .6rem; text-wrap: balance; }
33	h3 { font-size: 1.08rem; margin: 1.3rem 0 .3rem; text-wrap: balance; }
34	h4 { font-size: 1rem; margin: 1.1rem 0 .3rem; }
35	p { margin: 0 0 .8rem; }
36	p, li, dd { max-width: 65ch; }
37	ul, ol { margin: 0 0 .9rem; padding-left: 1.2rem; }
38	li { margin-bottom: .35rem; }
39	li > p:last-child { margin-bottom: 0; }
40	dl { margin: 0 0 .9rem; }
41	dt { font-weight: 700; margin-top: .5em; }
42	dd { margin: .1em 0 0 1.2em; }
43	a { color: var(--accent); }
44	a:focus-visible, button:focus-visible, summary:focus-visible, textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
45	/* Code inside a sentence keeps its highlight, with almost no padding at its sides, so that the
46	   quotation marks around it sit close, as in the PDF. Ligatures are off wherever code is shown: the specification's point is
47	   often the ASCII characters themselves, and a ligature would hide them. */
48	code { font-family: var(--mono); font-size: .9em; background: var(--code-bg); padding: .08em .1em; border-radius: 3px; overflow-wrap: anywhere; }
49	code, pre, .tt, .m .kw, .m .op, .m .str, .fx-r { font-variant-ligatures: none; font-feature-settings: "liga" 0, "clig" 0, "calt" 0, "dlig" 0; }
50	code.ul { text-decoration: underline; }
51	strong { font-weight: 700; }
52	blockquote { margin: 0 0 .9rem; padding-left: 1rem; border-left: 3px solid var(--rule); }
53	.center { text-align: center; }
54	.sc { font-variant: small-caps; } .sf { font-family: var(--body); } .rm { font-style: normal; font-family: var(--math); }
55	.it { font-style: italic; } .bf { font-weight: 700; } .tt { font-family: var(--mono); font-size: .9em; }
56	
57	/* the bar */
58	nav.bar { position: sticky; top: 0; z-index: 5; display: flex; gap: 12px; align-items: center; justify-content: space-between;
59	  margin-inline: calc(-1 * max(16px, env(safe-area-inset-left))) calc(-1 * max(16px, env(safe-area-inset-right)));
60	  padding: 8px max(16px, env(safe-area-inset-right)) 8px max(16px, env(safe-area-inset-left));
61	  background: var(--bg); border-bottom: 1px solid var(--rule); font-size: .88rem; }
62	nav.bar a { text-decoration: none; font-weight: 700; white-space: nowrap; padding: 4px 0; }
63	nav.bar .here { color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; flex: 1; text-align: center; }
64	nav.bar .count { font-family: var(--mono); font-weight: 600; font-size: .78rem; border: 1px solid var(--rule); border-radius: 999px; padding: 0 .5em; margin-left: .3em; background: var(--surface); }
65	[id] { scroll-margin-top: 56px; }
66	
67	#resume:empty, #chapter-notes:empty, #continue:empty, #storage-warning:empty { display: none; }
68	header.masthead { display: flex; flex-direction: column; gap: .4rem; }
69	header.masthead h1 { margin: 0; }
70	.eyebrow { font-family: var(--mono); font-size: .78rem; color: var(--muted); letter-spacing: .02em; margin: 0; max-width: none; }
71	.standfirst { color: var(--muted); margin: 0 0 .8rem; }
72	.num { font-family: var(--mono); font-size: .78em; font-weight: 400; color: var(--muted); letter-spacing: .02em; }
73	h1 .num { display: block; font-size: .78rem; margin-bottom: .2rem; }
74	
75	nav.parts { border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule); padding: 12px 0 4px; margin: 0 0 1rem; }
76	nav.parts { -webkit-user-select: none; user-select: none; }
77	nav.parts h2 { font-size: 1rem; margin: 0 0 .3rem; }
78	nav.parts ol { columns: 2 16rem; margin: 0 0 .5rem; list-style: none; padding: 0; }
79	nav.parts li { break-inside: avoid; }
80	nav.parts a, details.secs a { text-decoration: none; }
81	.nb-tools { text-align: right; margin: -.8rem 0 .3rem; line-height: 1; }
82	
83	details.words { background: var(--surface); border: 1px solid var(--rule); border-radius: 8px; padding: 8px 14px; font-size: .9rem; min-width: 0; }
84	details.words > summary { cursor: pointer; color: var(--muted); line-height: 1.4; padding: 2px 0; }
85	details.words > summary .w-head { font-weight: 700; color: var(--fg); margin-right: .4rem; }
86	details.words[open] > summary { margin-bottom: .4rem; }
87	details.words ul { margin: 0 0 .3rem; }
88	
89	section.part { border-top: 1px solid var(--rule); padding-top: 18px; min-width: 0; }
90	section.sec { min-width: 0; }
91	section.sec > section.sec { border-top: 1px solid var(--rule); padding-top: 18px; margin-top: 22px; }
92	section.sec > section.sec > section.sec { border-top: 0; padding-top: 0; margin-top: 0; }
93	
94	footer.colophon { border-top: 1px solid var(--rule); padding-top: 12px; font-size: .88rem; color: var(--muted); }
