96	/* the Select button of the revival page, and the note button beside it */
97	button.sel, .addnote { font-family: var(--mono); font-size: .72rem; font-weight: 600; color: var(--accent); background: var(--surface); border: 1px solid var(--rule); border-radius: 4px; padding: .2em .6em; margin-left: .6rem; vertical-align: .15em; cursor: pointer; -webkit-user-select: none; user-select: none; line-height: 1.4; }
98	button.sel::before { content: "Select"; }
99	.addnote::before { content: "✎"; font-size: .95rem; line-height: 1; }
100	.addnote { border-color: transparent; background: none; color: var(--muted); opacity: .55; padding: .25em .55em; margin-left: .25rem; vertical-align: baseline; }
101	span.addnote { border: 0; padding: .3em .5em; margin-left: 0; white-space: nowrap; }
102	span.addnote:focus-visible { outline: 2px solid var(--accent); }
103	h1 .addnote, h2 .addnote, h3 .addnote, h4 .addnote { opacity: .8; border-color: var(--rule); background: var(--surface); vertical-align: .15em; margin-left: .4rem; }
104	.has-note > .addnote, .has-note > .fx-bar .addnote { color: var(--accent); opacity: 1; }
105	.addnote:hover { opacity: 1; }
