107	/* math and code as the specification renders them */
108	.m { font-family: var(--math); font-size: 1.06em; font-style: normal; white-space: nowrap; }
109	.m i { font-style: italic; }
110	.m .kw, .m .op, .m .str, .m .tt { font-family: var(--mono); font-size: .82em; }
111	.m .kw { font-weight: 600; }
112	.m .ty, .m .rm { font-style: normal; }
113	.m .big { font-size: 1.35em; line-height: 1; vertical-align: -.1em; }
114	.m sup, .m sub { font-size: .72em; line-height: 0; }
115	.m .frac { display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: .85em; line-height: 1.15; }
116	.m .frac > span:first-child { border-bottom: 1px solid currentColor; padding: 0 .2em; }
117	.m .frac > span:last-child { padding: 0 .2em; }
118	.m .ovl { border-top: 1px solid currentColor; } .m .unl { border-bottom: 1px solid currentColor; }
119	.m table { display: inline-table; vertical-align: middle; border-collapse: collapse; }
120	.cm { font-family: var(--body); font-size: .88em; color: var(--muted); white-space: nowrap; }
121	p .m, li .m, dd .m, td .m { white-space: normal; }
122	.dm { overflow-x: auto; margin: 0 0 .9rem; padding: 4px 0; text-align: center; }
