124	.fx, pre.vb, .tw { position: relative; margin: 0 0 .9rem; }
125	.fx { background: var(--surface); border: 1px solid var(--rule); border-radius: 6px; }
126	.fx-r { overflow-x: auto; padding: 10px 12px; -webkit-overflow-scrolling: touch; }
127	.fx-r .tb { display: inline-block; vertical-align: top; white-space: nowrap; }
128	.fx-r .tb.top { display: block; width: max-content; min-width: 100%; }
129	.fx-r .l { display: block; line-height: 1.6; min-height: .5em; }
130	.fx-r .gapline { display: block; height: .4em; }
131	.fx.tt .fx-r { font-family: var(--mono); font-size: .86rem; }
132	pre { font-family: var(--mono); font-size: .84rem; line-height: 1.5; margin: 0; overflow-x: auto; -webkit-overflow-scrolling: touch; }
133	pre code { background: none; padding: 0; font-size: 1em; overflow-wrap: normal; white-space: pre; }
134	pre.fx-s { padding: 10px 12px; background: var(--code-bg); border-top: 1px solid var(--rule); border-radius: 0 0 5px 5px; }
135	.fx > pre.fx-s:first-child { border-top: 0; border-radius: 5px; }
136	pre.vb { padding: 10px 12px; background: var(--code-bg); border: 1px solid var(--rule); border-radius: 6px; }
137	.fx-bar { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 3px 6px 3px 12px; border-bottom: 1px solid var(--rule); font-family: var(--mono); font-size: .72rem; color: var(--muted); -webkit-user-select: none; user-select: none; }
138	.fx-bar .seg { display: inline-flex; border: 1px solid var(--rule); border-radius: 4px; overflow: hidden; }
139	.fx-bar .seg button { font: inherit; font-weight: 600; color: var(--muted); background: none; border: 0; padding: .25em .7em; cursor: pointer; }
140	.fx-bar .seg button[aria-pressed="true"] { background: var(--code-bg); color: var(--accent); }
141	.fx-bar .seg button.r::before { content: "Rendered"; } .fx-bar .seg button.s::before { content: "Source"; }
142	html[data-code="rendered"] .fx.both > .fx-s, html[data-code="source"] .fx.both > .fx-r { display: none; }
143	html[data-code="source"] .fx.both > .fx-s { border-top: 0; }
144	pre.vb > .addnote, .tw > .addnote, .dm > .addnote { position: absolute; top: 2px; right: 2px; background: var(--surface); border-color: var(--rule); opacity: .9; }
145	.fx > .addnote { position: absolute; top: 2px; right: 2px; background: var(--surface); border-color: var(--rule); opacity: .9; }
