147	.tw { overflow-x: auto; -webkit-overflow-scrolling: touch; padding-right: 2.2rem; }
148	table.tab, table.grammar { border-collapse: collapse; font-size: .92rem; }
149	table.tab td { padding: 3px 12px 3px 0; vertical-align: top; white-space: nowrap; }
