184	/* where he left off, notes, export */
185	.resume, .chapter-notes, .warn { background: var(--surface); border: 1px solid var(--rule); border-left: 4px solid var(--accent); border-radius: 0 8px 8px 0; padding: 10px 14px; font-size: .94rem; }
