203	.note-card .meta button { font-size: .72rem; padding: .3em .7em; min-height: 30px; }
204	button.act.primary, a.act.primary { background: var(--accent); color: var(--bg); border-color: var(--accent); }
205	button.act.danger, .note-card .meta button.danger { color: #b3261e; }
