1	/* The reader of the Fortress specification: the Select buttons, the place where the
2	   reader stopped, notes along the text, and their export and import.
3	   Everything is kept in this browser's localStorage; the pages work without it. */
4	(function () {
5	  'use strict';
6	  var BASE = 'https://palimondo.github.io/fortress/specification/';
7	  var K_NOTES = 'fortress-spec.notes.v1', K_PLACE = 'fortress-spec.place.v1', K_CODE = 'fortress-spec.code.v1';
8	  var body = document.body, kind = body.getAttribute('data-page'), slug = body.getAttribute('data-slug');
9	  var chapterTitle = body.getAttribute('data-chapter');
10	
11	  /* ---------- storage, with a fallback in memory ---------- */
12	  var mem = {}, storageOK = true;
13	  try {
14	    window.localStorage.setItem('fortress-spec.probe', '1');
15	    window.localStorage.removeItem('fortress-spec.probe');
16	  } catch (e) { storageOK = false; }
17	  function load(key, dflt) {
18	    if (storageOK) {
19	      try {
20	        var s = window.localStorage.getItem(key);
21	        if (s != null) return JSON.parse(s);
22	      } catch (e) { /* fall through to memory */ }
23	    }
24	    return key in mem ? mem[key] : dflt;
25	  }
26	  function save(key, value) {
27	    mem[key] = value;
28	    if (!storageOK) return false;
29	    try { window.localStorage.setItem(key, JSON.stringify(value)); return true; }
30	    catch (e) { return false; }
31	  }
32	  function notes() { var n = load(K_NOTES, []); return Array.isArray(n) ? n : []; }
33	  function saveNotes(list) { var ok = save(K_NOTES, list); updateCount(); return ok; }
34	
35	  function el(tag, cls, text) {
36	    var e = document.createElement(tag);
37	    if (cls) e.className = cls;
38	    if (text != null) e.textContent = text;
39	    return e;
40	  }
41	  function words(text, n) {
42	    var w = text.replace(/\u2060/g, '').replace(/\s+/g, ' ').trim().split(' ');
43	    return w.length > n ? w.slice(0, n).join(' ') + ' …' : w.join(' ');
44	  }
45	  function updateCount() {
46	    var link = document.querySelector('nav.bar .notes-link');
47	    if (!link) return;
48	    var c = link.querySelector('.count'), n = notes().length;
49	    if (!n) { if (c) c.remove(); return; }
50	    if (!c) { c = el('span', 'count'); link.appendChild(c); }
51	    c.textContent = n;
52	  }
53	  function storageWarning(target) {
